// ***************
// Filename: reset_ctrl_regs.sv
// Author: FPGA Cores 4 U
// Description: Register map of reset_ctrl: its AXI4-Lite register slave
//   (axi4_lite_slave front end) with every register of the block, the ID
//   block first; the registers go to reset_ctrl's logic on named ports, its
//   status comes back on input ports. Reset controller: software reset, hold
//   time, status, reset event count. Generated by ip/scripts/regmap_gen.py
//   from reset_ctrl_regs.json: edit the JSON and regenerate (the IP_VERSION /
//   IP_DATE stamps are kept).
//   Register map (ADDR_W = 8, byte offsets):
//     0x00 ID          RO   "RSTC" IP identifier, 4 ASCII characters (first
//                       in [31:24])
//     0x04 VERSION     RO   version, ASCII "d.dd" (+0.01 at every source
//                       update)
//     0x08 DATE        RO   date of the last source update, BCD mm/dd/yyyy
//                       (0xMMDDYYYY)
//     0x0C reserved    RO   0
//     0x10 CTRL        WO   write 1: software reset of the reset outputs
//                       (self clearing)
//     0x14 HOLD        RW   clocks the reset outputs stay asserted after a
//                       request, reset HOLD_RST
//     0x18 STATUS      CMD  status; write 1 to [1] to clear EVENT
//                       [0] ACTIVE: reset output 0 asserted
//                       [1] EVENT: a reset happened (W1C)
//     0x1C EVENT_COUNT RO   resets counted
//   Access: RW read / write (byte strobes), RO read only (writes answer
//   SLVERR), W1C hardware sets / software writes 1 to clear (a set wins), W1S
//   software writes 1 to set / hardware clears, WO write only (reads 0), CMD
//   reads the hardware value, a write gives a pulse with its data. Unmapped
//   words read 0 and ignore writes; above the map: DECERR. Clock - aclk.
//   Reset - synchronous active low aresetn. Latency - 2 clocks per write and
//   read.
// Date: 2026-10-12
module reset_ctrl_regs #(
  parameter int HOLD_RST = 16  // HOLD at reset (HOLD_DEFAULT)
) (
  input  logic          aclk,           // clock
  input  logic          aresetn,        // synchronous reset, active low
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  input  logic [7:0]    s_axil_awaddr,  // AXI4-Lite
  input  logic          s_axil_awvalid,
  output logic          s_axil_awready,
  input  logic [31:0]   s_axil_wdata,
  input  logic [3:0]    s_axil_wstrb,
  input  logic          s_axil_wvalid,
  output logic          s_axil_wready,
  output logic [1:0]    s_axil_bresp,
  output logic          s_axil_bvalid,
  input  logic          s_axil_bready,
  input  logic [7:0]    s_axil_araddr,
  input  logic          s_axil_arvalid,
  output logic          s_axil_arready,
  output logic [31:0]   s_axil_rdata,
  output logic [1:0]    s_axil_rresp,
  output logic          s_axil_rvalid,
  input  logic          s_axil_rready,
  output logic          ctrl_o,         // CTRL (WO): data written
  output logic          ctrl_wr_o,      // CTRL: one-clock pulse at every software write
  output logic [16-1:0] hold_o,         // HOLD (RW): register value
  output logic          hold_wr_o,      // HOLD: one-clock pulse at every software write
  input  logic [2-1:0]  status_i,       // STATUS (CMD): value read
  output logic [2-1:0]  status_o,       // STATUS (CMD): data written
  output logic          status_wr_o,    // STATUS: one-clock pulse at every software write
  input  logic [32-1:0] event_count_i   // EVENT_COUNT (RO): value read
);
  // ---------------- register map
  localparam logic [31:0] IP_ID      = "RSTC";
  localparam logic [31:0] IP_VERSION = "1.10";
  localparam logic [31:0] IP_DATE    = 32'h10122026;   // mm/dd/yyyy, BCD
  localparam logic [7:0] A_ID = 8'h0, A_VERSION = 8'h4, A_DATE = 8'h8;
  localparam logic [7:0] A_CTRL = 8'h10;
  localparam logic [7:0] A_HOLD = 8'h14;
  localparam logic [7:0] A_STATUS = 8'h18;
  localparam logic [7:0] A_EVENT_COUNT = 8'h1C;
  localparam int MAP_WORDS = 8;

  logic             wr_en, rd_en, wr_err_q;
  logic [7:0]       wr_addr, rd_addr, rd_addr_q;
  logic [31:0]      wr_data, rd_data;
  logic [3:0]       wr_strb;
  axi4_lite_slave #(
    .ADDR_W(8),
    .READ_WAIT(0),
    .MAP_WORDS(MAP_WORDS)
  ) u_axil (
    .aclk(aclk),
    .aresetn(aresetn),
    .s_axil_awaddr,
    .s_axil_awvalid,
    .s_axil_awready,
    .s_axil_wdata,
    .s_axil_wstrb,
    .s_axil_wvalid,
    .s_axil_wready,
    .s_axil_bresp,
    .s_axil_bvalid,
    .s_axil_bready,
    .s_axil_araddr,
    .s_axil_arvalid,
    .s_axil_arready,
    .s_axil_rdata,
    .s_axil_rresp,
    .s_axil_rvalid,
    .s_axil_rready,
    .wr_en_o(wr_en),
    .wr_addr_o(wr_addr),
    .wr_data_o(wr_data),
    .wr_strb_o(wr_strb),
    .wr_err_i(wr_err_q),
    .rd_en_o(rd_en),
    .rd_addr_o(rd_addr),
    .rd_data_i(rd_data),
    .rd_valid_i(1'b1),
    .rd_err_i(1'b0)
  );
  wire [7:0] wa = {wr_addr[7:2], 2'b00};
  // byte strobes applied to the written word
  logic [31:0] wmask;
  always_comb for (int b = 0; b < 4; b++) wmask[b*8 +: 8] = {8{wr_strb[b]}};

  // ---------------- writes
  logic [31:0] ctrl_q;
  logic [31:0] hold_q;
  logic [31:0] status_q;
  always_ff @(posedge aclk) begin
    if (!aresetn) begin
      ctrl_q <= '0;
      ctrl_wr_o <= 1'b0;
      hold_q <= 32'(HOLD_RST);
      hold_wr_o <= 1'b0;
      status_q <= '0;
      status_wr_o <= 1'b0;
      wr_err_q <= 1'b0;
    end else begin
      wr_err_q <= wr_en && (wa == A_ID || wa == A_VERSION || wa == A_DATE || wa == A_EVENT_COUNT);   // writes to read-only words: SLVERR
      begin
        ctrl_wr_o <= wr_en && wa == A_CTRL;
        if (wr_en && wa == A_CTRL) ctrl_q <= (ctrl_q & ~wmask) | (wr_data & wmask);
      end
      begin
        hold_wr_o <= wr_en && wa == A_HOLD;
        if (wr_en && wa == A_HOLD) hold_q <= (hold_q & ~wmask) | (wr_data & wmask);
      end
      begin
        status_wr_o <= wr_en && wa == A_STATUS;
        if (wr_en && wa == A_STATUS) status_q <= (status_q & ~wmask) | (wr_data & wmask);
      end
    end
  end
  assign ctrl_o = ctrl_q[1-1:0];
  assign hold_o = hold_q[16-1:0];
  assign status_o = status_q[2-1:0];

  // ---------------- reads: the word addressed in the clock before
  always_ff @(posedge aclk) if (rd_en) rd_addr_q <= {rd_addr[7:2], 2'b00};
  always_comb begin
    rd_data = '0;
    case (rd_addr_q)
      A_ID:      rd_data = IP_ID;
      A_VERSION: rd_data = IP_VERSION;
      A_DATE:    rd_data = IP_DATE;
      A_HOLD: rd_data = hold_q;
      A_STATUS: rd_data = 32'(status_i);
      A_EVENT_COUNT: rd_data = 32'(event_count_i);
      default: begin
      end
    endcase
  end
endmodule
